<script setup lang="ts">
import{computed,ref}from'vue';import{useI18n}from'vue-i18n';import{getTool}from'../registry';import{computeHashes}from'./hash'
const{t}=useI18n();const tool=getTool('soc-tools.hash');const input=ref('');const output=ref('');const error=ref('');const mode=ref<'text'|'hex'>('text');const uppercase=ref(false);const copied=ref(false);let run=0;const inputBytes=computed(()=>new TextEncoder().encode(input.value).byteLength);const isOverLimit=computed(()=>inputBytes.value>tool.recommendedMaxInputBytes)
async function transform(){const current=++run;error.value='';copied.value=false;if(!input.value){output.value='';return}try{const hashes=await computeHashes(input.value,mode.value);if(current!==run)return;output.value=Object.entries(hashes).map(([name,digest])=>`${name}: ${uppercase.value?digest.toUpperCase():digest}`).join('\n')}catch{if(current===run){output.value='';error.value=t('tools.hash.invalid')}}}function clear(){run+=1;input.value='';output.value='';error.value='';copied.value=false}async function copyOutput(){if(output.value){await navigator.clipboard.writeText(output.value);copied.value=true}}
</script>
<template><section class="tool-page" aria-labelledby="tool-title"><header class="tool-heading"><span class="category">{{ t(`categories.${tool.category}`) }}</span><h1 id="tool-title">{{ t(tool.nameKey) }}</h1><p>{{ t(tool.descriptionKey) }}</p></header><div class="io-panel"><div class="terminal-titlebar"><span class="window-marks" aria-hidden="true"><i /><i /><i /></span><span>[ hash ]</span></div><div class="io-strip"><fieldset><legend>{{ t('tools.hash.inputMode') }}</legend><label class="radio-control"><input v-model="mode" type="radio" value="text" @change="transform"><span>{{ t('tools.hash.text') }}</span></label><label class="radio-control"><input v-model="mode" type="radio" value="hex" @change="transform"><span>{{ t('tools.hash.hex') }}</span></label></fieldset><label class="check-control"><input v-model="uppercase" type="checkbox" @change="transform">{{ t('tools.hash.uppercase') }}</label><span class="byte-count">{{ inputBytes }} B</span><div class="strip-actions"><button class="icon-button" type="button" :disabled="!output" :aria-label="copied?t('common.copied'):t('common.copy')" @click="copyOutput"><svg aria-hidden="true" viewBox="0 0 24 24"><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M15 9V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h3" /></svg></button><button class="icon-button" type="button" :aria-label="t('common.clear')" @click="clear"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m-9 0 1 14h8l1-14" /></svg></button></div></div><p class="notice warning" role="note">{{ t('tools.hash.limitation') }}</p><p v-if="isOverLimit" class="notice warning" role="status">{{ t('common.warning',{size:'5 MB'}) }}</p><div class="editor-grid"><div class="field"><label for="hash-input"><span>$</span> {{ t('common.input') }}</label><div class="terminal-editor input-editor"><span class="editor-prompt" aria-hidden="true">$</span><textarea id="hash-input" v-model="input" :class="{invalid:error}" :aria-invalid="Boolean(error)" :aria-describedby="error?'hash-error':undefined" :placeholder="t('tools.hash.placeholder')" spellcheck="false" @input="transform" /></div></div><div class="field"><label for="hash-output"><span>&gt;</span> {{ t('common.output') }}</label><div class="terminal-editor"><span class="editor-prompt" aria-hidden="true">&gt;</span><textarea id="hash-output" :value="output" :placeholder="t('common.result')" readonly /></div></div></div><p v-if="error" id="hash-error" class="notice error" role="alert">{{ error }}</p></div></section></template>
